<style>.tpa-table{min-width:720px;border:1px solid #dfe6ee;border-collapse:collapse;font-family:var(--body)}.tpa-table th,.tpa-table td{padding:14px;border:1px solid #e1e7ee;font-family:var(--body);font-size:12px}.tpa-table th{background:#f1f5f9;color:#34495c;font-weight:700;letter-spacing:.02em;text-transform:none}.status-assigned{color:#168bd2;border-color:#8bc8eb}.status-fix{color:#d95167;border-color:#ec9da8}.status-ok{color:#25a565;border-color:#90d7af}.portal-note{margin-bottom:18px;border-color:#cfe0ed;background:#f5faff;color:#4d6477}.tpa-tools{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0;padding:8px;border-radius:7px;background:#f2f6fa}.tpa-tools button{padding:9px 14px;border:0;border-radius:5px;background:transparent;color:#607284;cursor:pointer;font:500 12px var(--body)}.tpa-tools button.active{background:#168bd2;color:#fff}.tpa-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin:0 0 18px}.tpa-summary>div{display:flex;align-items:center;gap:12px;padding:16px 18px;border:1px solid #e0e7ef;border-radius:12px;background:#fff;box-shadow:0 4px 14px rgba(29,55,82,.07)}.tpa-summary b{display:grid;place-items:center;width:40px;height:40px;border-radius:50%;background:#e8f4ff;color:#168bd2}.tpa-summary span{color:#536779;font-size:12px;font-weight:600}.tpa-summary .wait b{background:#fff3dc;color:#cf8a18}.tpa-summary .fix b{background:#ffebed;color:#d95868}.tpa-summary .done b{background:#e5f8ee;color:#25a565}.card{border:1px solid #e0e7ef;border-radius:12px;box-shadow:0 5px 18px rgba(29,55,82,.08)}.card>.eyebrow{color:#263e55;font:700 14px var(--body);letter-spacing:.02em;text-transform:none}.actions .btn{border-radius:6px}@media(max-width:900px){.tpa-summary{grid-template-columns:1fr 1fr}}@media(max-width:520px){.tpa-summary{grid-template-columns:1fr}}</style>
<div class="notice portal-note">Anda login sebagai TPA bidang <b><?= ucfirst($bidang) ?></b>. Hanya konsultasi yang secara khusus ditugaskan kepada Anda yang ditampilkan.</div><?php if($this->session->flashdata('sukses')):?><div class="notice"><?= htmlspecialchars($this->session->flashdata('sukses')) ?></div><?php endif;?>
<?php $ts=array('ditugaskan'=>0,'perlu_perbaikan'=>0,'direkomendasikan'=>0);foreach($daftar as $x){if(isset($ts[$x['status']]))$ts[$x['status']]++;} ?>
<div class="tpa-summary"><div><b><?= count($daftar) ?></b><span>Total Penugasan</span></div><div class="wait"><b><?= $ts['ditugaskan'] ?></b><span>Belum Direview</span></div><div class="fix"><b><?= $ts['perlu_perbaikan'] ?></b><span>Perlu Perbaikan</span></div><div class="done"><b><?= $ts['direkomendasikan'] ?></b><span>Sudah Sesuai</span></div></div>
<div class="card"><p class="eyebrow">Daftar Penugasan</p><div class="tpa-tools" role="group" aria-label="Filter status"><button class="active" data-filter="semua">Semua</button><button data-filter="ditugaskan">Belum Direview</button><button data-filter="perlu_perbaikan">Perlu Perbaikan</button><button data-filter="direkomendasikan">Sudah Sesuai</button></div><div class="table-wrap"><table class="tpa-table"><thead><tr><th>Nama Pemohon</th><th>Nomor Registrasi</th><th>Putaran</th><th>Status</th><th>Ditugaskan</th><th>Aksi</th></tr></thead><tbody><?php if(empty($daftar)):?><tr><td colspan="6">Belum ada konsultasi yang ditugaskan kepada Anda.</td></tr><?php endif;?><?php foreach($daftar as $r):?><tr data-status="<?= htmlspecialchars($r['status']) ?>"><td><?= htmlspecialchars($r['nama_pemohon']) ?></td><td><b><?= htmlspecialchars($r['nik']?:'—') ?></b><br><small><?= htmlspecialchars($r['no_permohonan']) ?></small></td><td><b><?= (int)$r['putaran'] ?></b><br><small><?= (int)$r['putaran']>1?'Lanjutan perbaikan':'Penugasan awal' ?></small></td><td><span class="badge <?= $r['status']==='direkomendasikan'?'status-ok':($r['status']==='perlu_perbaikan'?'status-fix':'status-assigned') ?>"><?= konsultasi_label_status($r['status']) ?></span></td><td><?= date('d/m/Y H:i',strtotime($r['assigned_at'])) ?></td><td><div class="actions"><?php if($r['status']==='ditugaskan'):?><a class="btn btn-primary" href="<?= base_url('tpa-pengajuan-pbg/review/'.$r['id']) ?>"><?= (int)$r['putaran']>1?'Review Ulang':'Review' ?></a><?php else:?><a class="btn" href="<?= base_url('tpa-pengajuan-pbg/review/'.$r['id']) ?>">Lihat Hasil</a><a class="btn" target="_blank" href="<?= base_url('pengajuan-pbg/berita-acara/'.$r['id']) ?>">Unduh BA</a><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></div>
<script>document.querySelectorAll('.tpa-tools button').forEach(function(b){b.addEventListener('click',function(){document.querySelectorAll('.tpa-tools button').forEach(function(x){x.classList.remove('active')});b.classList.add('active');document.querySelectorAll('.tpa-table tbody tr[data-status]').forEach(function(r){r.hidden=b.dataset.filter!=='semua'&&r.dataset.status!==b.dataset.filter})})});</script>
